        'caption/small/bold': captionSmallBold,
        'caption/small/extra-bold': captionSmallExtraBold,
      };
}

/// One shadow layer from `effects/*`. `inner` layers cannot be a BoxShadow.
@immutable
class LooviShadow {
  const LooviShadow({required this.color, required this.offset, required this.blur, required this.spread, this.inner = false});
  final Color color;
  final Offset offset;
  /// Figma blur radius (= CSS blur).
  final double blur;
  final double spread;
  final bool inner;
  BoxShadow toBoxShadow() => BoxShadow(color: color, offset: offset, blurRadius: blur, spreadRadius: spread);
}

/// Elevation and state effects (`effects/*`).
@immutable
class LooviEffects {
  const LooviEffects._();
  /// `effects/elevation/0`
  List<LooviShadow> get elevation0 => const [LooviShadow(color: Color(0x00000000), offset: Offset(0.0, 0.0), blur: 0.0, spread: 0.0)];
  /// `effects/elevation/1`
  List<LooviShadow> get elevation1 => const [LooviShadow(color: Color(0x143A3345), offset: Offset(0.0, 8.0), blur: 8.0, spread: 0.0)];
  /// `effects/elevation/2`
  List<LooviShadow> get elevation2 => const [LooviShadow(color: Color(0x1F3A3345), offset: Offset(0.0, 16.0), blur: 24.0, spread: 0.0)];
  /// `effects/elevation/3`
  List<LooviShadow> get elevation3 => const [LooviShadow(color: Color(0x293A3345), offset: Offset(0.0, 32.0), blur: 40.0, spread: 0.0)];
  /// `effects/elevation/inverse-1`
  List<LooviShadow> get elevationInverse1 => const [LooviShadow(color: Color(0x52000000), offset: Offset(0.0, 8.0), blur: 8.0, spread: 0.0)];
  /// `effects/elevation/inverse-2`
  List<LooviShadow> get elevationInverse2 => const [LooviShadow(color: Color(0x7A000000), offset: Offset(0.0, 16.0), blur: 24.0, spread: 0.0)];
  /// `effects/elevation/inverse-3`
  List<LooviShadow> get elevationInverse3 => const [LooviShadow(color: Color(0xA3000000), offset: Offset(0.0, 32.0), blur: 40.0, spread: 0.0)];
  /// `effects/effect/pressed`
  List<LooviShadow> get effectPressed => const [LooviShadow(color: Color(0xCC5A78FF), offset: Offset(0.0, 0.0), blur: 4.0, spread: 0.0)];
  /// `effects/effect/focus`
  List<LooviShadow> get effectFocus => const [LooviShadow(color: Color(0xFFFFFFFF), offset: Offset(0.0, 0.0), blur: 0.0, spread: 4.0, inner: true)];
  /// Drop-shadow layers as BoxShadow (inner layers skipped).
  static List<BoxShadow> box(List<LooviShadow> layers) => [for (final l in layers) if (!l.inner) l.toBoxShadow()];
}

