/// All product-theme component tokens for one mode.
@immutable
class LooviComponentTokens {
  const LooviComponentTokens({required this.appHeader, required this.button, required this.modalHeader, required this.input, required this.inputTextarea, required this.listAction, required this.modal, required this.sectionHeader});
  final LooviAppHeaderTokens appHeader;
  final LooviButtonTokens button;
  final LooviModalHeaderTokens modalHeader;
  final LooviInputTokens input;
  final LooviInputTextareaTokens inputTextarea;
  final LooviListActionTokens listAction;
  final LooviModalTokens modal;
  final LooviSectionHeaderTokens sectionHeader;
  /// Mode `escritorio-virtual`.
  static const LooviComponentTokens escritorioVirtual = LooviComponentTokens(appHeader: LooviAppHeaderTokens.escritorioVirtual, button: LooviButtonTokens.escritorioVirtual, modalHeader: LooviModalHeaderTokens.escritorioVirtual, input: LooviInputTokens.escritorioVirtual, inputTextarea: LooviInputTextareaTokens.escritorioVirtual, listAction: LooviListActionTokens.escritorioVirtual, modal: LooviModalTokens.escritorioVirtual, sectionHeader: LooviSectionHeaderTokens.escritorioVirtual);
  /// Mode `site-loovi`.
  static const LooviComponentTokens siteLoovi = LooviComponentTokens(appHeader: LooviAppHeaderTokens.siteLoovi, button: LooviButtonTokens.siteLoovi, modalHeader: LooviModalHeaderTokens.siteLoovi, input: LooviInputTokens.siteLoovi, inputTextarea: LooviInputTextareaTokens.siteLoovi, listAction: LooviListActionTokens.siteLoovi, modal: LooviModalTokens.siteLoovi, sectionHeader: LooviSectionHeaderTokens.siteLoovi);
  /// Mode `app-cliente`.
  static const LooviComponentTokens appCliente = LooviComponentTokens(appHeader: LooviAppHeaderTokens.appCliente, button: LooviButtonTokens.appCliente, modalHeader: LooviModalHeaderTokens.appCliente, input: LooviInputTokens.appCliente, inputTextarea: LooviInputTextareaTokens.appCliente, listAction: LooviListActionTokens.appCliente, modal: LooviModalTokens.appCliente, sectionHeader: LooviSectionHeaderTokens.appCliente);
  static LooviComponentTokens forMode(LooviProductMode mode) => switch (mode) {
        LooviProductMode.escritorioVirtual => escritorioVirtual,
        LooviProductMode.siteLoovi => siteLoovi,
        LooviProductMode.appCliente => appCliente,
      };
}

